<!-- <form action="/form.php" method="POST">
	<input name="test1">
	<input name="test2">
	<input type="submit">
</form> -->

<!-- 254 Получение данных форм в PHP -->
<!--
Пусть у нас есть файл form.php, а в нем HTML форма, отправляющаяся на страницу result.php.
На этой странице мы можем получить данные формы с помощью специальных переменных $_GET, $_POST и $_REQUEST.
Эти переменные содержат в себе массив данных отправленной формы.
При этом ключами этого массива будут имена инпутов, а значениями - те данные, которые были введены в эти инпуты.
При этом, если форма была отправлена методом GET, то данные будут в массиве $_GET,
а если методом POST, то данные будут соответственно в массиве $_POST.
А в переменной $_REQUEST будут лежать данные формы, отправленные любым из методов. -->

<!-- 255 Получение данных форм методом GET в PHP -->

<!-- Давайте посмотрим на примере. Пусть файл form.php содержит форму, отправляющуюся методом GET на страницу formt.php: -->
<!-- <form action="/form.php" method="GET">
	<input name="test1">
	<input name="test2">
	<input type="submit">
</form> -->
<!-- Если в нашу форму в браузере вбить какие-то данные и нажать на кнопку, то форма отправится на страницу form.php: -->
<!-- <?php
	var_dump($_GET);     // массив с ключами test1 и test2
	var_dump($_POST);    // пустой массив
	var_dump($_REQUEST); // массив с ключами test1 и test2
?> -->

<!-- А можно вывести на экран содержимое определенного инпута: -->
<!-- <?php
	echo $_GET['test1'];
?> -->

<!-- А можно взять содержимое и первого, и второго инпутов, слить их в строку и вывести на экран: -->
<!-- <?php
	echo $_GET['test1'] . $_GET['test2'];
?> -->
<!--
Сделайте форму с тремя инпутами. Пусть в эти инпуты вводятся числа. После отправки формы выведите на экран сумму этих чисел. -->
<!-- <form action="/form.php" method = "GET">
	<input name="num1">
	<input name="num2">
	<input name="num3">
	<input type="submit">
</form> -->

<!-- 256 Получение данных форм методом POST в PHP -->

<!-- Пусть теперь наша форма отправляется методом POST: -->
<!-- <form action="/form.php" method="POST">
	<input name="test1">
	<input name="test2">
	<input type="submit">
</form> -->

<!-- В этом случае на странице результата данные формы будут лежать в переменной $_POST: -->
<!-- <?php
	var_dump($_GET);     // пустой массив
	var_dump($_POST);    // массив с ключами test1 и test2
	var_dump($_REQUEST); // массив с ключами test1 и test2
?> -->

<!-- С помощью формы спросите у пользователя его имя и возраст. После отправки формы выведите эти данные на экран. -->
<!-- <form action="/form.php" method="POST">
	<input name="name">
	<input name="age">
	<input type="submit">
</form> -->

<!-- Пусть с помощью формы у пользователя спрашивается пароль: -->

<!-- <form action="/form.php" method="POST">
	<input type="password" name="pass">
	<input type="submit">
</form> -->
