<!-- Нас ждет проблема - если флажок не отмечен, то, так как в форме кроме чекбокса нет других элементов,
в $_GET будет лежать пустой массив. Это значит, что в коде обработки формы мы не попадем в первый if, проверяющий отправку формы.
Для решения проблемы используют специальный прием: создают скрытый инпут с таким же именем, как и у нашего чекбокса.
При этом значением скрытого инпута ставят ноль, а чебокса - единицу: -->
