<!-- 282 Введение в работу с куками в PHP -->

<!-- Существует способ сохранения данных прямо в браузере пользователя. Это делается с помощью кук (cookie). 
Куки - это небольшие кусочки строк, которые хранятся в специальном месте в браузере. Каждая кука имеет свое имя, 
по которому эту куку можно записать и прочитать.
Давайте посмотрим, как это делается. Для начала сделаем два PHP файла. В первом файле мы запишем куку, а во втором - прочитаем ее.
Запись кук делается с помощью функции setcookie, которая первым параметром принимает имя этой куки, а вторым - значение. 
При этом запись кук нужно делать до любого вывода на экран (подобно сессиям).
Итак, давайте в файле запишем куку с именем test и значением 'abcde': -->
<!-- <?php
	//setcookie('test', 'abcde');
?> -->

<!-- Давайте теперь во втором файле прочитаем нашу куку. Это делается с помощью массива $_COOKIE: -->
<!-- <?php
	//echo $_COOKIE['test']; // выведет 'abcde'
?> -->

<!-- 283 Проблема установки кук в PHP -->
<!-- 
При записи и чтении куки на одной странице нас будет поджидать некоторый подвох. 
Дело в том, что куки, установленные через setcookie, становятся доступными в массиве $_COOKIE только после перезагрузки страницы.
Давайте проверим это. Запишем через setcookie какую-то куку и сразу выведем ее на экран. 
В этом случае при первом заходе в $_COOKIE для нашей куки будет null, а при уже обновлении страницы - значение куки: -->
<!-- <?php
	//setcookie('str', 'eee');
	//var_dump($_COOKIE['str']); // сначала null, а потом 'eee'
?> -->

<!-- 284 Мгновенная установка кук в PHP -->

