index.php
/dir1/
/dir2/
test.txt -->
<!-- <?php
echo file_get_contents('newnew/new1/new1.txt');
?> -->

<!-- 293 Абсолютные пути в PHP -->

<!-- Давайте прочитаем текстовый файл, находящийся в папке с нашим скриптом: -->
<!-- <?php
	echo file_get_contents('test.txt');
?> -->

<!-- Давайте теперь в начале пути поставим слеш: -->
<!-- <?php
	echo file_get_contents('/test.txt');
?> -->

<!-- В этом случае путь станет не относительным, а абсолютным. При этом наш файл будет искаться от корня операционной системы. 
Конечно же, файла по такому пути не найдется, так как он расположен в папке с нашем сайтом.
Мы можем получить путь от корня операционной системы до папки с нашим сайтом: -->
<!-- <?php
	echo $_SERVER['DOCUMENT_ROOT'];
?> -->
<!-- 
Можем добавить полученный путь к имени искомого файла - и получим правильный абсолютный путь к нашему файлу: -->
