	$res = mysqli_query($link, $query1) or die(mysqli_error($link));
	for ($data = []; $row = mysqli_fetch_assoc($res); $data[] = $row);
    echo'<pre>';
    print_r($data);
    echo'<pre>';
?> -->
<!-- 
330 Вставка записей через SQL запрос в PHP -->

